다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int main(void) {
    int a = 9, b = 2;
    int p = a / b * b;
    double q = (double)a / b;
    printf("%d %.1f", p, q + a % b);
    return 0;
}

다음 C 프로그램의 실행 결과는? (단, unsigned char의 크기는 8비트이다)

[코드]
#include <stdio.h>
int main(void) {
    int v = 0x203;
    int c = (unsigned char)v;
    int m = 24, n = 2;
    m /= n + 2;
    printf("%d", c + m);
    return 0;
}

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int main(void) {
    int a = 5, b = 8, c;
    c = a++ + --b;
    printf("%d %d ", c, a);
    printf("%d ", b--);
    printf("%d", b);
    return 0;
}

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int main(void) {
    int n = 3, s = 0;
    while (n-- > 0)
        s = s * 2 + n;
    printf("%d %d", s, n);
    return 0;
}

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int next(void) {
    static int s = 1;
    int t = 6;
    s += 3;
    t -= 4;
    return s + t;
}
int main(void) {
    int i, r = 0;
    for (i = 0; i < 3; i++)
        r = next();
    printf("%d", r);
    return 0;
}

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int main(void) {
    int a = 0, b = 3, c = 3;
    if (a && ++b)
        c += 10;
    if (!a || ++c)
        b *= 2;
    printf("%d", b + c);
    return 0;
}

