다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int main(void) {
    int k = 0, sum = 0;
    while (k < 7) {
        k++;
        if (k % 2 == 0 && k % 3 != 0)
            sum += k;
    }
    printf("%d", sum);
    return 0;
}

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int main(void) {
    int a = 1, b = 2, t, i;
    for (i = 0; i < 4; i++) {
        t = a;
        a = b;
        b = t + b;
    }
    printf("%d %d", a, b);
    return 0;
}

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int main(void) {
    int k = 5, c = 0;
    while (k < 5) {
        c += 1;
        k++;
    }
    do {
        c += 10;
        k++;
    } while (k < 5);
    printf("%d %d", c, k);
    return 0;
}

