다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int main(void) {
    int v[6] = {5, 8, 0, 3};
    int i, n, z = 0;
    n = sizeof(v) / sizeof(v[0]);
    for (i = 0; i < n; i++)
        if (v[i] == 0)
            z++;
    printf("%d %d", n, z);
    return 0;
}

