다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
struct S { int a; int b; };
union U { int a; int b; };
int main(void) {
    struct S s;
    union U u;
    s.a = 2; s.b = 5;
    u.a = 2; u.b = 5;
    printf("%d ", s.a + s.b);
    printf("%d", u.a + u.b);
    return 0;
}

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int main(void) {
    char w[] = "banana";
    int i, c = 0;
    w[4] = '\0';
    for (i = 0; w[i] != '\0'; i++)
        if (w[i] == 'a')
            c++;
    printf("%s %d", w, c);
    return 0;
}

